<?php

/* @autogenerated */
declare(strict_types=1);

require_once __DIR__ . '/FormsTestCase.php';

use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\ScopesConsentForm;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Scopes\Application\Usecase\ScopesConsentUsecase;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\Gateway\ScopesConsentGateway;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\ScopePermission;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;
use DI\ContainerBuilder;
use Slim\Psr7\Factory\ServerRequestFactory;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;

/**
 * Unit tests for {@see ScopesConsentForm} step integration.
 */
#[AllowMockObjectsWithoutExpectations]
final class ScopesConsentFormStepUnitTest extends FormsTestCase
{
    public function testAuthenticateStoresApprovedScopesAndProceeds(): void
    {
        $input = $this->buildInputWithScope(
            ['optional_scopes' => ['email']],
            new ChallengesState(username: 'user-1'),
            'openid email profile'
        );

        $gateway = $this->createMock(ScopesConsentGateway::class);
        $gateway->expects($this->once())
            ->method('pendingScopes')
            ->with('tenant1', 'user-1', 'client-123', ['openid', 'email', 'profile'])
            ->willReturn([
                new ScopePermission('openid', true),
                new ScopePermission('email', false),
            ]);
        $gateway->expects($this->once())
            ->method('storeAcceptedScopes')
            ->with('tenant1', 'user-1', 'client-123', ['openid', 'email']);

        $scopesConsent = new ScopesConsentUsecase($gateway);

        $authResponse = $this->createMock(PublicLoginAuthResponse::class);
        $authenticator = $this->createMock(AuthenticateUser::class);
        $authenticator->expects($this->once())
            ->method('preAuthenticate')
            ->with(
                $this->callback(function (AuthenticationRequest $request): bool {
                    $this->assertSame('openid email', $request->scope);
                    return true;
                }),
                $input->challenges,
                'tenant1',
                $input->context->issuer,
                'csid-123',
                $input->context->state,
                $input->context->nonce
            )
            ->willReturn($authResponse);

        $form = new ScopesConsentForm(
            $this->createMock(MessageProvider::class),
            $authenticator,
            $scopesConsent,
            $this->createMock(DecorateHtml::class),
            $this->createMock(HtmlSecurer::class)
        );

        $result = $form->authenticate($input);

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertSame($authResponse, $result->authResponse);
        $this->assertSame($input->challenges, $result->challenges);
    }

    public function testAuthenticateRejectsWhenNoScopesApproved(): void
    {
        $input = $this->buildInputWithScope([], new ChallengesState(username: 'user-1'), 'openid email');

        $gateway = $this->createMock(ScopesConsentGateway::class);
        $gateway->expects($this->once())
            ->method('pendingScopes')
            ->with('tenant1', 'user-1', 'client-123', ['openid', 'email'])
            ->willReturn([
                new ScopePermission('email', false),
            ]);
        $gateway->expects($this->never())
            ->method('storeAcceptedScopes');

        $scopesConsent = new ScopesConsentUsecase($gateway);

        $form = new ScopesConsentForm(
            $this->createMock(MessageProvider::class),
            $this->createMock(AuthenticateUser::class),
            $scopesConsent,
            $this->createMock(DecorateHtml::class),
            $this->createMock(HtmlSecurer::class)
        );

        try {
            $form->authenticate($input);
            $this->fail('Expected LoginException');
        } catch (LoginException $exception) {
            $this->assertSame(AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED, $exception->auth->error);
        }
    }

    private function buildInputWithScope(array $body, ChallengesState $state, string $scope): StepInput
    {
        $body = array_merge(['csid' => 'csid-123'], $body);
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => $scope,
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $authRequest = new AuthenticationRequest(
            client: new ClientData('client-123', ['code'], true),
            scope: $scope,
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );

        return new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $state,
            body: $body,
            request: $request
        );
    }
}
